package net.neoforged.neoforge.registries;import java.util.*;import java.util.function.*;import net.neoforged.bus.api.IEventBus;public class DeferredRegister{public String id;public Object registry;public boolean registered;public Map<String,Holder>entries=new HashMap<>();public record Holder(Supplier<?>supplier){public Object get(){return supplier.get();}}public static DeferredRegister create(Object registry,String id){DeferredRegister r=new DeferredRegister();r.id=id;r.registry=registry;return r;}public Holder register(String name,Supplier<?>supplier){if(entries.containsKey(name))throw new AssertionError("duplicate");Holder h=new Holder(supplier);entries.put(name,h);return h;}public void register(IEventBus b){registered=true;}}